export const GLOSSARY_SHARD = Object.freeze({"proof-of-stake":{"slug":"proof-of-stake","cat":"basics","en":"Proof of stake (PoS)","contentLocale":"id","term":"Proof of stake (PoS)","aka":["PoS","bukti kepemilikan"],"short":"Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya.","body":[["Pada PoS, tidak ada perlombaan komputasi seperti ",["penambangan","mining"],". Jaringan memilih ",["validator","validator"]," untuk mengusulkan dan mengesahkan blok, biasanya dengan peluang yang sebanding dengan jumlah koin yang di-stake. Validator jujur mendapat imbalan, sedangkan validator yang curang atau sering offline bisa terkena slashing, yaitu pemotongan sebagian jaminannya."],[["Ethereum","ethereum"]," beralih ke PoS pada September 2022 lewat The Merge, sehingga konsumsi energinya turun drastis. Solana, Cardano, dan banyak jaringan lain juga memakai varian PoS. Detail seperti jumlah minimum stake, periode penguncian, dan aturan slashing berbeda di setiap jaringan."],["Bagi pengguna biasa, PoS membuka peluang ",["staking","staking"],". Anda bisa mendelegasikan koin ke validator, staking lewat exchange, atau memakai ",["liquid staking","liquid-staking"],". Imbalannya tidak tetap dan bergantung pada aturan jaringan serta jumlah total koin yang di-stake."]],"example":"Misalkan Anda melakukan staking 10 SOL melalui seorang validator. Jaringan memberikan imbalan sekitar 7% per tahun sebelum potongan, dan validator mengenakan komisi 10% dari imbalan itu. Imbalan kotor setahun 0,7 SOL, komisi validator 0,07 SOL, sehingga Anda menerima sekitar 0,63 SOL. Angka ini ilustrasi, karena tingkat imbalan sebenarnya berubah-ubah.","mistakes":["Mengira imbalan staking PoS adalah bunga tetap yang dijamin.","Tidak memeriksa periode unstaking, sehingga dana tidak bisa dijual cepat saat dibutuhkan.","Memilih validator hanya karena komisinya paling murah tanpa melihat rekam jejak uptime-nya."],"faq":[{"q":"Apakah proof of stake lebih aman dari proof of work?","a":"Keduanya punya model keamanan berbeda. PoW bergantung pada biaya energi, PoS bergantung pada nilai koin yang dipertaruhkan dan ancaman slashing."},{"q":"Apakah saya perlu menjadi validator untuk ikut PoS?","a":"Tidak. Anda bisa mendelegasikan koin ke validator atau staking lewat exchange atau protokol liquid staking tanpa menjalankan server sendiri."}],"title":"Apa itu proof of stake (PoS)? Arti dan cara kerja","description":"Pelajari arti proof of stake, peran validator dan slashing, serta bagaimana PoS membuka peluang staking bagi pengguna biasa.","related":[["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan."],["validator","Validator","Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru."],["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"volatility":{"slug":"volatility","cat":"basics","en":"Volatility","contentLocale":"id","term":"Volatility (volatilitas)","aka":["volatilitas","volatil"],"short":"Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu.","body":[["Aset dengan volatilitas tinggi bisa berubah harga 5% sampai 20% dalam sehari, sedangkan aset dengan volatilitas rendah bergerak lebih tenang. Kripto umumnya jauh lebih volatil daripada saham besar atau emas, dan ",["altcoin","altcoin"]," kecil biasanya lebih volatil daripada ",["Bitcoin","bitcoin"],". ",["Stablecoin","stablecoin"]," dirancang agar volatilitasnya sangat rendah."],["Secara statistik, volatilitas sering diukur dengan standar deviasi return, atau dengan indikator seperti ATR (average true range). Dalam praktik, trader cukup melihat rentang harga harian atau mingguan untuk menyesuaikan ",["ukuran posisi","position-sizing"]," dan jarak ",["stop loss","stop-loss"],"."],["Volatilitas sangat penting saat memakai ",["leverage","leverage"],". Pergerakan harga 10% pada leverage 10x setara dengan perubahan 100% pada margin Anda, cukup untuk likuidasi. Volatilitas juga biasanya naik saat ada berita besar atau rilis data ekonomi."]],"example":"Misalkan koin A biasanya bergerak sekitar 2% per hari dan koin B sekitar 8% per hari. Anda ingin rugi maksimal 20 USDT per transaksi dengan stop loss sejauh pergerakan harian. Untuk koin A, ukuran posisinya sekitar 20 / 2% = 1.000 USDT. Untuk koin B, ukuran posisinya hanya 20 / 8% = 250 USDT. Risiko yang sama menghasilkan ukuran posisi yang sangat berbeda.","mistakes":["Memakai ukuran posisi dan leverage yang sama untuk Bitcoin dan memecoin kecil.","Memasang stop loss terlalu dekat pada aset yang sangat volatil sehingga cepat tersentuh oleh pergerakan biasa.","Mengira volatilitas hanya berarti harga turun, padahal juga berarti kenaikan tajam."],"faq":[{"q":"Kenapa harga kripto sangat volatil?","a":"Pasar kripto relatif muda, buka 24 jam, banyak memakai leverage, dan sangat dipengaruhi sentimen serta berita. Likuiditas yang tipis pada koin kecil memperbesar pergerakan."},{"q":"Apakah volatilitas tinggi itu buruk?","a":"Tidak sepenuhnya. Volatilitas memberi peluang untung bagi trader, tetapi juga memperbesar kerugian, sehingga ukuran posisi perlu disesuaikan."}],"title":"Apa itu volatilitas di kripto? Arti dan cara mengukurnya","description":"Pelajari arti volatilitas, kenapa kripto lebih bergejolak, dan cara menyesuaikan ukuran posisi serta stop loss dengannya.","related":[["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"stop-limit-order":{"slug":"stop-limit-order","cat":"trading","en":"Stop-limit order","contentLocale":"id","term":"Stop limit order","aka":["stop limit","order stop limit"],"short":"Stop limit order adalah order yang aktif saat harga menyentuh harga stop, lalu otomatis memasang limit order di harga limit yang Anda tentukan.","body":[["Stop limit memiliki dua harga. Harga stop adalah pemicunya. Harga limit adalah harga terburuk yang masih Anda terima. Setelah pemicu tersentuh, ",["limit order","limit-order"]," dikirim ke ",["order book","order-book"]," dan hanya terisi di harga limit atau lebih baik."],["Kelebihannya, Anda terlindung dari ",["slippage","slippage"]," ekstrem. Kekurangannya, jika harga turun sangat cepat melewati harga limit, order bisa tidak terisi sama sekali dan posisi Anda tetap terbuka. Karena itu banyak trader memberi jarak antara harga stop dan limit, misalnya 0,3% sampai 1% tergantung ",["volatilitas","volatility"],"."],["Stop limit juga bisa dipakai untuk masuk posisi saat harga menembus level tertentu, misalnya membeli setelah breakout di atas ",["resistance","support-and-resistance"],". Pada futures, beberapa exchange memakai ",["mark price","mark-price"]," atau harga terakhir sebagai pemicu, jadi periksa opsi pemicunya."]],"example":"Misalkan Anda memegang 100 LINK yang dibeli di 15,00 USDT. Anda memasang stop limit jual dengan harga stop 14,00 dan harga limit 13,90 USDT. Jika harga turun bertahap, order aktif di 14,00 dan terisi di sekitar 13,90 sampai 14,00, kerugian sekitar 100 sampai 110 USDT. Namun jika harga langsung anjlok dari 14,10 ke 13,50, limit 13,90 tidak terisi dan Anda masih memegang posisi di harga 13,50.","mistakes":["Menyamakan harga stop dan harga limit pada aset yang volatil, sehingga order mudah tidak terisi.","Mengira stop limit selalu menutup posisi seperti stop market.","Tidak memeriksa apakah pemicu memakai harga terakhir atau mark price."],"faq":[{"q":"Apa beda stop limit dan stop market?","a":"Stop market mengirim market order saat pemicu tersentuh, sehingga pasti terisi tetapi bisa slippage. Stop limit mengirim limit order, sehingga harga terkendali tetapi bisa tidak terisi."},{"q":"Berapa jarak ideal antara harga stop dan limit?","a":"Tidak ada angka pasti. Jarak perlu cukup lebar untuk volatilitas normal aset tersebut agar order tetap terisi, tetapi tidak terlalu jauh hingga kehilangan fungsi perlindungannya."}],"title":"Apa itu stop limit order? Arti dan cara kerjanya","description":"Arti stop limit order, peran harga stop dan harga limit, bedanya dengan stop market, dan risiko order tidak terisi.","related":[["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."],["trailing-stop","Trailing stop","Trailing stop adalah stop order yang otomatis mengikuti harga ketika bergerak menguntungkan Anda dengan jarak tetap, lalu menutup posisi ketika harga berbalik sejauh jarak itu."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi"},"coin":null,"tool":null,"cta":false},"time-in-force":{"slug":"time-in-force","cat":"trading","en":"Time in force (GTC, IOC, FOK)","contentLocale":"id","term":"Time in force (GTC, IOC, FOK)","aka":["TIF","GTC","IOC","FOK"],"short":"Time in force adalah pengaturan yang menentukan berapa lama sebuah order tetap aktif dan bagaimana order diperlakukan jika tidak bisa langsung terisi penuh, dengan opsi umum GTC, IOC, dan FOK.","body":[["GTC (good till canceled) berarti order tetap di ",["order book","order-book"]," sampai terisi atau Anda batalkan. Ini pengaturan bawaan untuk ",["limit order","limit-order"]," di banyak exchange. Beberapa platform tetap membatalkan order GTC yang sangat lama sesuai kebijakan mereka."],"IOC (immediate or cancel) berarti order harus terisi sebanyak mungkin seketika, lalu sisa yang tidak terisi langsung dibatalkan. FOK (fill or kill) lebih ketat: order harus terisi penuh seketika, jika tidak seluruh order dibatalkan dan tidak ada yang tereksekusi.",["IOC dan FOK berguna saat Anda ingin kepastian bahwa order tidak menggantung di order book, misalnya untuk ",["arbitrase","arbitrage"]," atau eksekusi bot. Pilihan yang tersedia dan namanya bisa berbeda antar exchange, sering ada di menu lanjutan form order."]],"example":["Misalkan di order book hanya ada 3 BNB dijual di 600 ",["USDT","usdt"],", lalu level berikutnya 602 USDT. Anda mengirim limit beli 5 BNB di 600 USDT. Dengan GTC, 3 BNB terisi dan 2 BNB sisanya menunggu di 600. Dengan IOC, 3 BNB terisi senilai 1.800 USDT dan 2 BNB sisanya dibatalkan. Dengan FOK, seluruh order dibatalkan karena 5 BNB tidak bisa terisi penuh di 600 USDT."],"mistakes":["Membiarkan order GTC lama tetap aktif lalu tiba-tiba terisi saat kondisi pasar sudah berubah.","Memakai FOK untuk jumlah besar di pasar tipis sehingga order terus dibatalkan.","Mengira IOC menjamin seluruh jumlah order terisi."],"faq":[{"q":"Apa arti GTC di exchange kripto?","a":"GTC berarti good till canceled, yaitu order tetap aktif di order book sampai terisi penuh atau Anda batalkan sendiri."},{"q":"Apa beda IOC dan FOK?","a":"IOC mengizinkan pengisian sebagian lalu membatalkan sisanya. FOK hanya mau terisi penuh seketika, jika tidak seluruh order dibatalkan."}],"title":"Apa itu time in force? Arti GTC, IOC, dan FOK","description":"Arti time in force di trading kripto, perbedaan GTC, IOC, dan FOK, serta contoh kapan masing-masing pengaturan berguna.","related":[["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."],["post-only-order","Post-only order","Post-only order adalah limit order yang hanya boleh masuk ke order book sebagai order maker, dan otomatis dibatalkan atau disesuaikan jika akan langsung tereksekusi sebagai taker."],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin."],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Pasar, limit, batalkan: apa yang diselesaikan masing-masing?"},"coin":null,"tool":null,"cta":false},"private-key":{"slug":"private-key","cat":"wallets-security","en":"Private key","contentLocale":"id","term":"Private key (kunci privat)","aka":["kunci privat","kunci pribadi","private key"],"short":"Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu.","body":[["Secara teknis private key adalah angka acak sangat besar, biasanya ditampilkan sebagai 64 karakter heksadesimal. Dari private key dihitung ",["public key","public-key"],", dan dari public key dihasilkan ",["alamat dompet","wallet-address"],". Perhitungan ini hanya berjalan satu arah: alamat bisa dibagikan, tetapi tidak bisa dipakai untuk menebak private key."],"Setiap kali Anda mengirim kripto, dompet memakai private key untuk membuat tanda tangan digital. Jaringan memeriksa tanda tangan itu dengan public key tanpa pernah melihat private key Anda. Inilah mengapa ungkapan not your keys, not your coins populer: tanpa private key, Anda hanya punya janji dari pihak lain.",["Di dompet modern, private key biasanya diturunkan dari ",["seed phrase","seed-phrase"],", jadi Anda jarang melihatnya langsung. Beberapa dompet menyediakan menu ekspor private key. Fitur ini sebaiknya hanya dipakai jika benar-benar perlu, karena private key yang tersalin ke tempat lain menambah titik rawan kebocoran."]],"example":["Misalnya alamat Anda berisi 2.000 ",["USDT","usdt"],". Anda mengekspor private key ke file teks untuk memindahkannya ke aplikasi lain, lalu lupa menghapus file itu. Beberapa minggu kemudian laptop terinfeksi malware pencuri data yang memindai file teks. Penyerang mengimpor private key ke dompetnya dan mengirim 2.000 USDT keluar. Transaksi itu sah di mata jaringan karena ditandatangani dengan kunci yang benar, sehingga tidak bisa dibatalkan."],"mistakes":["Menyimpan private key di file teks, catatan ponsel, atau pesan ke diri sendiri.","Mengira alamat dompet dan private key adalah hal yang sama sehingga ikut membagikannya.","Mengimpor private key ke aplikasi dompet yang tidak jelas asal-usulnya."],"faq":[{"q":"Apakah private key bisa diubah?","a":"Private key sebuah alamat tidak bisa diganti. Jika kunci bocor, satu-satunya cara adalah membuat dompet baru dan memindahkan aset ke alamat baru secepatnya."},{"q":"Apakah exchange memberi saya private key?","a":"Umumnya tidak. Di exchange, kunci dikelola oleh platform, dan Anda hanya memiliki saldo akun. Untuk memegang private key sendiri, Anda perlu dompet non-kustodian."}],"title":"Apa itu private key? Arti kunci privat di kripto","description":"Pelajari arti private key, hubungannya dengan public key dan alamat dompet, serta mengapa kunci ini tidak boleh dibagikan.","related":[["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["public-key","Public key (kunci publik)","Public key adalah kunci yang dihitung dari private key dan boleh diketahui orang lain, dipakai jaringan untuk memverifikasi tanda tangan transaksi serta menjadi dasar pembuatan alamat dompet."],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["multisig-wallet","Dompet multisig (multi-signature)","Dompet multisig adalah dompet yang membutuhkan beberapa tanda tangan dari kunci berbeda, misalnya 2 dari 3, sebelum sebuah transaksi bisa dijalankan."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"amm":{"slug":"amm","cat":"defi","en":"Automated market maker (AMM)","contentLocale":"id","term":"AMM (automated market maker)","aka":["automated market maker","pembuat pasar otomatis","AMM"],"short":"AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain.","body":[["Di ",["exchange terpusat","centralized-exchange"],", harga terbentuk dari pertemuan order beli dan jual di ",["order book","order-book"],". AMM menggantinya dengan pool berisi dua token dan sebuah rumus. Model paling terkenal adalah constant product x × y = k yang dipopulerkan Uniswap: hasil kali jumlah kedua token di pool harus tetap sama setelah setiap swap, di luar fee."],["Akibatnya, setiap kali Anda membeli token A dengan token B, jumlah A di pool berkurang dan harganya naik. Semakin besar transaksi dibanding ukuran pool, semakin besar pergeseran harga atau price impact. ",["Arbitrase","arbitrage"]," dari trader lain menjaga harga di AMM tetap dekat dengan ",["harga pasar","last-price"]," di tempat lain."],["Ada banyak variasi AMM. Curve memakai rumus khusus untuk pasangan stabil seperti ",["USDC","usdc"],"/",["USDT","usdt"],", sementara Uniswap v3 dan v4 memakai concentrated liquidity agar penyedia likuiditas bisa memilih rentang harga. Penyedia likuiditas mendapat fee dari setiap swap, tetapi menanggung risiko impermanent loss."]],"example":"Misalkan pool berisi 100 ETH dan 300.000 USDC, sehingga harga awal 3.000 USDC per ETH dan k = 30.000.000. Anda membeli ETH dengan 30.000 USDC. Isi USDC di pool menjadi 330.000, maka ETH di pool harus menjadi 30.000.000 dibagi 330.000, yaitu sekitar 90,91 ETH. Anda menerima sekitar 9,09 ETH, dengan harga rata-rata sekitar 3.300 USDC per ETH, atau 10% lebih mahal dari harga awal, sebelum fee.","mistakes":["Melakukan swap besar di pool kecil tanpa memeriksa price impact.","Mengira harga di AMM selalu sama dengan harga di exchange terpusat.","Menyamakan price impact dengan slippage, padahal price impact sudah bisa dihitung sebelum transaksi dikirim."],"faq":[{"q":"Apa beda AMM dan order book?","a":"Order book mencocokkan order beli dan jual dari trader. AMM menghitung harga dari rumus dan isi pool, sehingga selalu ada likuiditas selama pool tidak kosong."},{"q":"Siapa yang menyediakan dana di AMM?","a":"Penyedia likuiditas (liquidity provider) yang menyetor pasangan token ke pool dan menerima bagian dari fee swap sebagai imbalannya."}],"title":"Apa itu AMM? Arti automated market maker di DEX","description":"Pelajari cara kerja AMM, rumus x × y = k, price impact, dan peran liquidity provider di decentralized exchange.","related":[["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["impermanent-loss","Impermanent loss (kerugian tidak permanen)","Impermanent loss adalah selisih nilai antara menyetor token ke liquidity pool dan sekadar menyimpannya di dompet, yang muncul ketika harga kedua token di pool bergerak berbeda."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"staking":{"slug":"staking","cat":"defi","en":"Staking","contentLocale":"id","term":"Staking","aka":["staking kripto","stake","penguncian aset"],"short":"Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama.","body":[["Di jaringan ",["proof of stake","proof-of-stake"]," seperti ",["Ethereum","ethereum"],", Solana, atau Cardano, ",["validator","validator"]," dipilih untuk membuat dan memverifikasi blok berdasarkan jumlah koin yang di-stake. Sebagai imbalan, mereka mendapat reward dari penerbitan koin baru dan biaya transaksi. Validator yang berbuat curang atau sering offline bisa terkena penalti, termasuk slashing."],["Anda bisa staking dengan beberapa cara. Menjalankan validator sendiri, misalnya 32 ETH di Ethereum. Mendelegasikan ke validator lewat dompet. Memakai ",["liquid staking","liquid-staking"]," seperti Lido. Atau memakai produk staking di exchange, yang paling mudah tetapi bersifat kustodian."],"Hal yang perlu diperiksa: imbal hasil dibayar dalam koin, bukan rupiah atau dolar, sehingga nilai riilnya tetap mengikuti harga koin. Banyak jaringan punya masa unbonding, yaitu waktu tunggu sebelum koin bisa ditarik, dan lamanya berbeda di tiap jaringan dan produk exchange."],"example":["Misalnya Anda melakukan staking 2 ETH dengan imbal hasil contoh 3,5% per tahun. Setelah setahun Anda memperoleh sekitar 0,07 ETH, sehingga total menjadi 2,07 ETH. Jika harga ETH saat mulai 3.000 ",["USDT","usdt"],", nilai awal 6.000 USDT. Jika harga turun menjadi 2.500 USDT, total 2,07 ETH bernilai 5.175 USDT. Reward staking menambah jumlah koin, tetapi tidak melindungi Anda dari penurunan harga."],"mistakes":["Mengira reward staking adalah keuntungan pasti dalam rupiah atau dolar.","Tidak memeriksa masa unbonding sehingga dana tidak bisa dipakai saat dibutuhkan.","Memilih validator hanya karena komisi termurah tanpa melihat reputasi dan uptime-nya."],"faq":[{"q":"Apakah staking aman?","a":"Staking mengandung risiko harga koin, risiko slashing validator, risiko smart contract pada liquid staking, dan risiko platform jika memakai exchange. Tingkat risikonya tergantung cara staking yang Anda pilih."},{"q":"Apa beda staking di exchange dan di dompet sendiri?","a":"Di exchange, platform yang mengelola koin dan validator, sehingga praktis tetapi kustodian. Di dompet sendiri, Anda mendelegasikan langsung dan tetap memegang kunci."}],"title":"Apa itu staking kripto? Arti, cara kerja, dan risikonya","description":"Pelajari arti staking, cara kerja proof of stake, pilihan staking di dompet atau exchange, dan risiko seperti unbonding dan slashing.","related":[["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya."],["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi."],["validator","Validator","Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru."],["crypto-earn","Crypto Earn (produk simpanan kripto)","Crypto Earn adalah kategori produk di bursa yang memberi imbal hasil atas aset kripto yang Anda simpan, misalnya simpanan fleksibel, simpanan berjangka, staking, atau produk terstruktur."],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"total-value-locked":{"slug":"total-value-locked","cat":"defi","en":"Total value locked (TVL)","contentLocale":"id","term":"TVL (total value locked)","aka":["total value locked","nilai total terkunci","TVL"],"short":"TVL adalah total nilai aset kripto yang disetor ke sebuah protokol DeFi atau blockchain, dihitung dalam dolar AS, dan sering dipakai sebagai ukuran kasar seberapa besar sebuah protokol dipakai.","body":[["TVL menjumlahkan semua token yang berada di ",["smart contract","smart-contract"]," protokol, seperti dana di ",["liquidity pool","liquidity-pool"],", jaminan di protokol lending, atau koin di ",["liquid staking","liquid-staking"],", lalu mengalikannya dengan ",["harga pasar","last-price"],". Situs agregator data ",["DeFi","defi"]," menampilkan TVL per protokol dan per jaringan."],["TVL berguna untuk membandingkan ukuran, tetapi punya kelemahan. Karena dihitung dalam dolar, TVL ikut naik turun mengikuti harga token meski tidak ada setoran atau penarikan. Aset yang sama juga bisa terhitung dua kali, misalnya ",["ETH","ethereum"]," yang di-stake menjadi stETH lalu disetor lagi ke protokol lending."],"Untuk menilai protokol, lihat TVL bersama data lain: volume, pendapatan fee, jumlah pengguna, dan seberapa besar TVL ditopang insentif sementara. TVL yang melonjak karena program reward bisa cepat turun saat reward berhenti."],"example":"Misalnya sebuah protokol menampung 50.000 ETH saat harga ETH 3.000 USD, sehingga TVL-nya 150 juta USD. Seminggu kemudian harga ETH turun 20% menjadi 2.400 USD. Tanpa satu pun pengguna menarik dana, TVL turun menjadi 120 juta USD. Sebaliknya, jika TVL turun dari 150 juta menjadi 120 juta USD padahal harga ETH tetap, berarti sekitar 10.000 ETH benar-benar ditarik keluar.","mistakes":["Menganggap TVL besar berarti protokol pasti aman dari peretasan.","Membaca kenaikan TVL sebagai dana baru masuk padahal hanya karena harga token naik.","Membandingkan TVL antar situs data tanpa sadar metode perhitungannya berbeda."],"faq":[{"q":"Apakah TVL tinggi berarti protokol bagus?","a":"Tidak selalu. TVL menunjukkan ukuran, bukan keamanan atau keberlanjutan. Periksa juga pendapatan, audit, dan apakah TVL ditopang insentif sementara."},{"q":"Apa beda TVL dan kapitalisasi pasar?","a":"Kapitalisasi pasar adalah nilai semua token proyek di pasar. TVL adalah nilai aset yang disetor pengguna ke dalam protokol."}],"title":"Apa itu TVL? Arti total value locked di DeFi","description":"Pelajari arti TVL atau total value locked, cara menghitungnya, dan mengapa angka ini bisa menyesatkan jika dibaca sendirian.","related":[["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat."],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi."],["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya."],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"depeg":{"slug":"depeg","cat":"stablecoins","en":"Depeg","contentLocale":"id","term":"Depeg","aka":["de-peg","lepas patokan"],"short":"Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS.","body":[[["Stablecoin","stablecoin"]," dirancang agar nilainya tetap dekat dengan aset acuan, biasanya 1 dolar AS. Selisih kecil seperti 0,999 atau 1,001 itu normal karena ada biaya dan pergerakan permintaan. Disebut depeg ketika selisihnya besar atau bertahan lama, misalnya harga turun ke 0,97 dan tidak segera pulih."],["Penyebabnya beragam: keraguan terhadap cadangan penerbit, masalah di bank tempat cadangan disimpan, penarikan massal, kode ",["smart contract","smart-contract"]," yang bermasalah, atau desain algoritmik yang gagal menahan tekanan jual. Istilah ini juga dipakai untuk aset lain yang dipatok, misalnya token ",["liquid staking","liquid-staking"]," yang harganya jauh di bawah ",["ETH","ethereum"]," yang mendasarinya."],["Bagi trader, depeg berpengaruh langsung ke saldo. Jika Anda menyimpan modal dalam stablecoin yang depeg, nilai dalam rupiah atau dolar ikut turun. Di bursa, pasangan seperti ",["USDC","usdc"],"/",["USDT","usdt"]," juga bisa bergerak tajam, dan posisi yang memakai stablecoin itu sebagai margin bisa terdampak."]],"example":"Misalkan Anda memegang 5.000 USDC dan karena kabar buruk soal bank penyimpan cadangan, harganya sempat turun ke 0,90 USDT. Di atas kertas nilai Anda tinggal 4.500 USDT, rugi 500. Jika Anda panik menjual di harga itu lalu harga pulih ke 0,99 keesokan harinya, kerugian 500 USDT itu menjadi nyata. Sebaliknya, jika penerbit benar-benar tidak bisa menebus 1:1, menunggu bisa membuat kerugian lebih besar. Karena itu yang perlu Anda nilai adalah penyebab depeg, bukan hanya angkanya.","mistakes":["Menganggap semua stablecoin sama amannya padahal cadangan dan mekanisme penebusannya berbeda.","Panik menjual di dasar harga saat depeg sesaat tanpa mengecek penyebabnya.","Menaruh seluruh dana di satu stablecoin tanpa diversifikasi ke penerbit lain."],"faq":[{"q":"Apakah USDT pernah depeg?","a":"USDT pernah beberapa kali turun sedikit di bawah 1 dolar saat pasar tertekan, lalu kembali mendekati patokan. Riwayat ini menunjukkan bahwa stablecoin besar pun bisa bergerak saat kepercayaan goyah."},{"q":"Apa bedanya depeg sementara dan permanen?","a":"Depeg sementara terjadi karena tekanan jual sesaat sementara cadangan tetap utuh, sehingga harga pulih. Depeg permanen terjadi ketika mekanisme penebusan atau cadangannya benar-benar gagal."}],"title":"Apa itu depeg? Arti depeg stablecoin di kripto","description":"Pelajari arti depeg, penyebab stablecoin lepas dari patokan 1 dolar, dan cara menilai risikonya bagi saldo Anda.","related":[["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["algorithmic-stablecoin","Stablecoin algoritmik (algorithmic stablecoin)","Stablecoin algoritmik adalah stablecoin yang mencoba menjaga patokan harga lewat aturan kode dan insentif pasar, bukan lewat cadangan kas penuh atau jaminan berlebih."],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange."],["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false},"real-world-assets":{"slug":"real-world-assets","cat":"tokenized-assets","en":"Real-world assets (RWA)","contentLocale":"id","term":"Real World Assets (RWA, aset dunia nyata)","aka":["RWA","aset dunia nyata","tokenisasi aset"],"short":"Real World Assets (RWA) adalah aset dari dunia keuangan nyata, seperti surat utang negara, kredit, properti, emas, atau saham, yang kepemilikannya direpresentasikan sebagai token di blockchain.","body":[["Tokenisasi RWA bekerja dengan menyimpan aset asli lewat kustodian atau badan hukum khusus, lalu menerbitkan token yang mewakili klaim atas aset itu. Contohnya obligasi pemerintah AS yang ditokenisasi oleh berbagai penerbit, ",["emas tokenisasi","tokenized-gold"]," seperti PAXG, atau pinjaman kepada bisnis yang dibiayai lewat protokol kredit on-chain."],["Manfaatnya: aset bisa dipecah menjadi nominal kecil, ditransfer cepat, dan dipakai di protokol ",["DeFi","defi"]," sebagai jaminan atau sumber imbal hasil. Proyek seperti Ondo Finance menjadi contoh yang sering dibahas dalam sektor ini."],["Risikonya berbeda dari kripto murni. Nilai token bergantung pada kepercayaan pada penerbit, kustodian, dan struktur hukum. Banyak produk RWA mewajibkan ",["KYC","kyc"]," dan hanya tersedia untuk investor tertentu atau wilayah tertentu. Pastikan Anda memahami apakah token memberi hak atas aset atau sekadar mengikuti harga."]],"example":["Misalkan sebuah token RWA mewakili obligasi jangka pendek dengan imbal hasil sekitar 4% per tahun, dan Anda membeli senilai 2.500 ",["USDC","usdc"],". Setelah setahun, jika imbal hasil tetap dan biaya pengelolaan 0,15%, hasil bersih sekitar 2.500 kali 3,85%, yaitu 96,25 USDC. Bandingkan dengan menyimpan 2.500 USDC tanpa imbal hasil di dompet. Namun jika penerbit menghentikan penebusan atau kustodian bermasalah, Anda bisa kesulitan mengambil kembali dana, meski aset dasarnya sendiri relatif stabil."],"mistakes":["Menganggap RWA bebas risiko karena aset dasarnya obligasi atau emas.","Tidak mengecek siapa penerbit dan kustodian aset aslinya.","Mengira semua token RWA bisa dibeli dan ditebus bebas tanpa KYC."],"faq":[{"q":"Apa contoh RWA di kripto?","a":"Contohnya obligasi pemerintah yang ditokenisasi, emas tokenisasi seperti PAXG dan XAUT, saham tokenisasi, serta kredit swasta on-chain. Setiap jenis punya struktur dan risiko berbeda."},{"q":"Kenapa RWA banyak dibicarakan?","a":"Karena RWA menghubungkan imbal hasil keuangan tradisional dengan infrastruktur blockchain. Ini membuka akses baru, tetapi juga membawa risiko hukum dan kustodian dari dunia tradisional."}],"title":"Apa itu RWA (Real World Assets) di kripto?","description":"Pelajari arti RWA atau aset dunia nyata yang ditokenisasi, contohnya, cara kerjanya, dan risiko penerbit serta kustodian.","related":[["tokenized-treasuries","Obligasi pemerintah tokenisasi (tokenized treasuries)","Obligasi pemerintah tokenisasi adalah token blockchain yang didukung surat utang pemerintah, umumnya US Treasury bills jangka pendek, sehingga pemegangnya mendapat imbal hasil mirip bunga obligasi."],["tokenized-stocks","Saham tokenisasi (tokenized stocks)","Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam."],["tokenized-gold","Emas tokenisasi (tokenized gold)","Emas tokenisasi adalah token blockchain yang setiap unitnya didukung sejumlah emas fisik yang disimpan kustodian, misalnya PAXG dan XAUT yang masing-masing mewakili satu troy ounce emas."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."]],"lesson":null,"coin":{"slug":"ondo","name":"Ondo","symbol":"ONDO"},"tool":"/topics/tokenized-assets","cta":false}});
